INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(371600, 0, 3716, 0, 0, 8, 'The Underbog', 'The Underbog lies beneath Serpent Lake in Coilfang Reservoir, a drowned cavern where the fungus of the marsh grows unchecked. Bog giants and shamblers wade through its pools, underbats hang in the gloom, fen rays and lykul wasps drift over the water, and underbog lords and lurkers move among the giant mushrooms. The naga hold part of it: Wrathfin myrmidons, sentries and warriors keep watch, crying out for their master and for Illidan, and Murkblood Broken fight beside them. Its masters are a strange company. The fungal giant Hungarfen keeps close to a great plant of its own, the hydra Ghaz''an swims the deep water, a Broken hunter called Swamplord Musel''ek keeps a great bear as his pet, and at the cavern''s far end waits the Black Stalker. The sporelings of Sporeggar have errands here, and the Cenarion Expedition has druids to find.', 'zones/underbog.txt (map 546: area 3716 only); DB spawns map 546: Bog Giant 17723, Underbog Shambler 17871, Underbat 17724, Fen Ray 17731, Lykul Wasp 17732, Underbog Lord 17734, Underbog Lurker 17725, Wrathfin Myrmidon 17726, Sentry 17727, Warrior 17735, Murkblood Tribesman 17728, Spearman 17729, Healer 17730, Oracle 17771; bosses 17770, 18105, 17826 with Claw 17827, 17882; creature_text 17726, 17727, 17735 group 0 (For the Master!; Illidan reigns!; said on aggro by chance); creature_template 17826 display 18570 (BrokenMale); 17827 subname Swamplord Musel''ek''s Pet, display 2289 (DruidBearTauren); 18105 display 17528 (HydraOutland); 17770 display 17228 (FungalGiant); gameobject 182054 The Underspore beside Hungarfen; quests 9715, 9717, 9719 (Sporeggar''s errands); 9738 (the druids, told in the Slave Pens file)'),
(371601, 2, 3716, 1, 0, 8, 'Hungarfen', 'Hungarfen is a fungal giant, a hulking thing of cap and stalk that dwells in the Underbog among the bog giants and shamblers. Beside it grows a great plant known as the Underspore, and the giant keeps close to it. Hungarfen does not fight alone, for the cavern floor seems to answer it: around its foes small mushrooms spring up one after another, swelling until they burst in clouds of choking spores.', 'creature_template 17770 (type 5, display 17228 FungalGiant); fixed spawn 138367, map 546 only; gameobject 182054 The Underspore (map 546, beside Hungarfen; source of the Underspore Frond 24247); boss_hungarfen.cpp (Underbog Mushrooms spawn at random targets, grow and release Spore Cloud); quest 9717 (T''shu 17857, Sporeggar; QuestType 2, Flags 136; QuestSortID 3716)'),
(371602, 2, 3716, 2, 0, 8, 'Swamplord Musel''ek', 'Swamplord Musel''ek is a Broken who hunts for the naga in the Underbog, and he is deadly with a bow. He lays freezing traps, marks his quarry and picks it off with aimed shots, or looses volleys of arrows into a crowd, and he keeps a great bear called Claw as his pet. When the bear works itself into a frenzy, he shouts at it to obey him and kill the intruders at once. To his foes he promises a fight to the death, or that he will end it quickly.', 'creature_template 17826 (faction 74, display 18570 BrokenMale); fixed spawn 138500, map 546 only; boss_swamplord_muselek.cpp (Shoot, Multi-Shot, Freezing Trap, Hunter''s Mark, Aimed Shot, Knock Away; aggro group 1, kill group 2, death group 3, matching creature_text); creature_text 17826 groups 0 (Beast! Obey me! Kill them at once!, said through Claw''s Frenzy link, smart_scripts 17827 id 2 and 6) and 1 (We fight to the death!; I will end this quickly....); creature_template 17827 Claw, subname Swamplord Musel''ek''s Pet'),
(371603, 2, 3716, 3, 0, 8, 'The Black Stalker', 'The Black Stalker waits at the far end of the Underbog, a great beast of the marsh that stalks on long legs. It is no simple animal. It crackles with lightning, chaining bolts from one foe to the next and laying static charges upon them, and it can lift its enemies helplessly into the air and hurl them about, so that they come crashing down again.', 'creature_template 17882 (type 1, display 18194 Tripod model); boss_the_black_stalker.cpp; quest 9719 (Khn''nix 17866, Sporeggar; QuestType 2, Flags 136; QuestSortID 3716)'),
(371604, 3, 3716, 1, 0, 8, 'The Sanguine Hibiscus', 'The sporelings of Sporeggar use the sanguine hibiscus for a number of purposes, and their supply is running low. The flowers used to grow as thick as shrubs, Gzhun''tt explains, but now that the marsh''s water is falling they can be found only in the Underbog at Coilfang Reservoir, beneath Serpent Lake. Worse, the shamblers, bog giants and underbats down there are said to consider them a delicacy, so whoever would help must take the flowers from the creatures that eat them.', 'quest 9715 description (Gzhun''tt 17856, Sporeggar; QuestType 2, Flags 136; QuestSortID 3716: they used to grow thick as shrubs, but the lowering of the marsh''s water levels means that they can only be found now in the Underbog); quest 9714 (repeatable, QuestType 0, after 9715); creature_loot Sanguine Hibiscus 24246 (Bog Giant 17723, Underbat 17724, Underbog Shambler 17871 and others); gameobject 183385 Sanguine Hibiscus (map 546)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(371601, 1, 0, 255, 'To the sporelings of Sporeggar, Hungarfen is one of the leaders of the spore giants, with whom they are at war whether they like it or not. T''shu says the giant has tended the Underspore to perfection for millennia, and that it would break its spirit if something happened to the plant. All is fair in mushrooms and war, the sporelings say.', 'quest 9717 description (at war with the spore giants, whether we like it or not; all is fair in mushrooms and war; Hungerfen has been tending a very special plant, known as the Underspore, to perfection for millennia; it would break his spirit)'),
(371601, 2, 0, 255, 'Sorely wounded, Hungarfen roared in pain and stood its ground in a cloud of foul spores, but the fungal giant fell all the same, there beside the plant it kept so close to.', 'creature_text 17770 group 0 (Hungarfen roars in pain.) and boss_hungarfen.cpp (at 20 percent health it roots itself, emotes and casts Foul Spores)'),
(371601, 3, 0, 255, 'A frond cut from the Underspore went back to T''shu at Sporeggar, who made a sound much like snorting laughter. The spore giants'' morale would surely be at an all time low once they realized what had been done, the sporeling said, unless they were so incensed that they attacked again soon.', 'quest 9717 reward text (snorting laughter; morale of the spore giants at an all time low; or so incensed that they''ll attack us again soon)'),
(371602, 1, 0, 255, 'Earthbinder Rayge, a druid found alive in the Underbog, knows the truth about the bear. He and Windcaller Claw were jumped by Musel''ek while investigating, and the swamplord can control animals, even druids. Claw was caught in bear form and is now his pet, and Rayge dares not take cat form himself, or he would be next.', 'npc_text 9121 (gossip 7521: Claw and I were investigating this place when we were jumped by Swamplord Musel''ek. He can control animals, even druids! ... Claw was caught in bear form at the time, and is now the swamplord''s pet. I don''t dare change into cat form)'),
(371602, 2, 0, 255, 'Beaten down, the bear broke free of the swamplord''s hold and became Windcaller Claw again, a tauren druid. How embarrassing, he said, to be taken as a pet by a hunter. He owed his rescuers his life, but he would find his own way out now, and perhaps pick up Rayge along the way.', 'smart_scripts 17827 and action list 1782700 (at 20 percent health Claw leaves the fight, turns friendly, takes Windcaller Claw''s form 17894 and sits; gossip hello gives the Lost in Action credit); npc_text 9125 (gossip 7525: How embarrassing to be taken as a pet by a hunter! I owe you my life ... I''ll be able to find my way out. Maybe I''ll pick up Rayge along the way.); creature_template_model 17894 display 17309 (TaurenMale)'),
(371602, 3, 0, 255, 'Musel''ek fought on with bow and trap to the end and fell at last in the Underbog. His final words were for those who had beaten him, a grudging gasp of praise: well done.', 'creature_text 17826 group 3 (Well... done...), called by boss_swamplord_muselek.cpp JustDied (SAY_JUST_DIED = 3)'),
(371603, 1, 0, 255, 'To the sporelings she is an old terror. Khn''nix of Sporeggar names the marsh walkers the greatest danger to the sporelings through their history, and the Black Stalker the great mother of them all. With the spore giants already pressing on Sporeggar, the village cannot afford another attack from its ancient enemies, so Khn''nix wants her dead, and her brain brought back as proof.', 'quest 9719 description (Historically the greatest danger to my people has been from the marsh walkers; new problems from spore giants; eliminate the great mother of the marsh walkers, known as The Black Stalker; bring me her brain as proof)'),
(371603, 2, 0, 255, 'For all the lightning that crackled about the great beast and its strange hold over the air, the Black Stalker fell at the far end of the Underbog, and the storm died away.', 'boss_the_black_stalker.cpp (fixed spawn 138323, map 546 only; Levitate, Chain Lightning, Static Charge)'),
(371603, 3, 0, 255, 'Khn''nix did not revel in such butchery, but the pain the great mother and her brood had brought the sporelings over the centuries was unspeakable. Another of her progeny would transform to replace her, the sporeling knew, yet that would take time, and Sporeggar would have some breathing room from the marsh walkers for a while.', 'quest 9719 reward text (Normally I would not revel in such butchery; pain over the centuries is unspeakable; another of her progeny will transform to replace her, but that will take time and give us some breathing room)'),
(371604, 1, 0, 255, 'The flowers would do nicely, Gzhun''tt said, but Sporeggar can always use more of them, and anyone who finds their way back into the Underbog is welcome to gather another bunch from its shamblers, bog giants and underbats and bring it home to the sporelings.', 'quests 9715 and 9714 reward text (These will do nicely, but we can always use more. Perhaps you will find yourself in the Underbog again soon?); quest 9714 completion text (We can still use more of the sanguine hibiscus from the shamblers, bog giants and underbats of the Underbog)');
